from datetime import datetime, timedelta
from typing import List

class OrderLine:
    def __init__(self, order_id: str, sku: str, quantity: int):
        self.order_id = order_id
        self.sku = sku
        self.quantity = quantity

class Batch:
    def __init__(self, batch_id: str, sku: str, quantity: int, eta: datetime):
        self.batch_id = batch_id
        self.sku = sku
        self.quantity = quantity
        self.eta = eta
        self._allocations = set()

    def __gt__(self, other):
        if self.eta is None:
            return False
        if other.eta is None:
            return True
        return self.eta > other.eta

    def allocate(self, line: OrderLine):
        if self.can_allocate(line):
            self._allocations.add(line.order_id)
            self.quantity -= line.quantity

    def deallocate(self, line: OrderLine):
        if line.order_id in self._allocations:
            self._allocations.remove(line.order_id)
            self.quantity += line.quantity

    def can_allocate(self, line: OrderLine) -> bool:
        return self.sku == line.sku and self.quantity >= line.quantity and line.order_id not in self._allocations

    @property
    def available_quantity(self) -> int:
        return self.quantity - sum(line.quantity for line in self._allocations)

def allocate(line: OrderLine, batches: List[Batch]) -> str:
    batch = next(b for b in sorted(batches) if b.can_allocate(line))
    batch.allocate(line)
    return batch.batch_id
```

